head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.procJob = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.pJobTitl = js_jobtitl;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 재마감 처리 관리자만 보일 수 있도록
        // 2010.03.09 김봉석 대리 요청
        if (js_dep_cd === 'ZSYS') {
            btn_ReTrSend.setBackgroundImage("../img/btn_ReCls_d.gif");
            btn_ReTrSend.setDisabled(true);
            btn_ReTrSend.show("");
        } else {
            btn_ReTrSend.hide();
        }
        let vCurDate = $c.ut.cGetToday("yyyymmdd");
        // edt_TASK_DD.text = cGetMinusDate2(vCurDate, 1);     // 일년 날짜
        edt_TASK_DD.setValue(vCurDate);
        MaxTab_01.setSelectedTabIndex(1);
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        await scwin.listSync();
        scwin.btnDisable();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05930.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
