/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        await scwin.listSync();
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            txb_NEW_SNDRCV_DATA_CORR_YN.hide();
            txb_ADD_SNDRCV_DATA_CORR_YN.hide();
            txb_APPROV_EMP_NM.hide();
            txb_APPROV_TM.hide();
            // 팀장확인_20100625
            txb_TEAMLEADR_EMP_NM.hide();
            txb_TEAMLEADR_TM.hide();
            lb_TEAMLEADR_EMP_NM.hide();
            lb_TEAMLEADR_TM.hide();
            lb_NEW_SNDRCV_DATA_CORR_YN.hide();
            lb_ADD_SNDRCV_DATA_CORR_YN.hide();
            lb_APPROV_EMP_NM.hide();
            lb_APPROV_TM.hide();
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            txb_NEW_SNDRCV_DATA_CORR_YN.show("");
            txb_ADD_SNDRCV_DATA_CORR_YN.show("");
            txb_APPROV_EMP_NM.show("");
            txb_APPROV_TM.show("");
            // 팀장확인_20100625
            txb_TEAMLEADR_EMP_NM.show("");
            txb_TEAMLEADR_TM.show("");
            lb_TEAMLEADR_EMP_NM.show("");
            lb_TEAMLEADR_TM.show("");
            lb_NEW_SNDRCV_DATA_CORR_YN.show("");
            lb_ADD_SNDRCV_DATA_CORR_YN.show("");
            lb_APPROV_EMP_NM.show("");
            lb_APPROV_TM.show("");

            // 팀장승인 disable
            scwin.btnDisable();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05930.MaxTab_01_OnSelChanged" });
    }
};

