/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const urltaskdd = "&TASK_DD=" + edt_TASK_DD.getValue();
    let url;
    url += urltaskdd;
    const sbmOptions = {
        id : "sbm_dts_Get_ListDD",
        action : "/ElwListedReceive.do",
        ref : "",
        target : "dts_Get_ListDD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += urltaskdd;
    const sbmOptions2 = {
        id : "sbm_dts_Item",
        action : "/ElwListedReceive.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.setButton();
    const urllistdd = "&LIST_DD=" + edt_LIST_DD.getValue();
    // alert('[urllistdd]'+urllistdd);
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        // alert("vListMdCd :"+vListMdCd);

        /*
        var url_new;
        url_new = "/ElwListedReceive.do?method=listElwNewListingTrSend&inputMessageId=ELW_NEWLISTING_TR_SEND_INOUT";
        url_new += urllistdd;
         */

        url_new += "&SCREN_ID=" + "ULDSTF05930.xml";
        url_new += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_New_Proc",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_New_Proc=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        /*
        var url_add;
        url_add = "/ElwListedReceive.do?method=listElwAddListingTrSend&inputMessageId=ELW_ADDLISTING_TR_SEND_INOUT";
        url_add += urllistdd;
         */

        url_add += "&SCREN_ID=" + "ULDSTF05930.xml";
        url_add += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions2 = {
            id : "sbm_dts_Add_Proc",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_Add_Proc=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        /*
        var url_new;
        url_new = "/ElwListedReceive.do?method=listElwNewListingTrSendSearch&inputMessageId=ELW_NEWLISTING_TR_SEND_INOUT";
        url_new += urllistdd;
         */
        url_new += "&SCREN_ID=" + "ULDSTF05930.xml";
        url_new += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_New_Search",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_New_Search=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        /*
        var url_add;
        url_add = "/ElwListedReceive.do?method=listElwAddListingTrSendSearch&inputMessageId=ELW_ADDLISTING_TR_SEND_INOUT";
        url_add += urllistdd;
         */

        url_add += "&SCREN_ID=" + "ULDSTF05930.xml";
        url_add += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions2 = {
            id : "sbm_dts_Add_Search",
