/**
 * @method
 * @name isuDelCheck
 * @description 종목 삭제여부체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isuDelCheck = async function() {
    let isTrue = false;

    /*
    var url;
    url = "/ElwListedReceive.do?method=readElwDeleteCheck&inputMessageId=ELW_LISTING_ISU_DEL_CHK_OUT";
    url += "&LIST_DD=" + getObjectValue(edt_LIST_DD);
     */

    const sbmOptions = {
        id : "sbm_dts_IsuDelChk",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_IsuDelChk=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert('dts_IsuDelChk.CountRow'+dts_IsuDelChk.CountRow);
    if (dts_IsuDelChk.getRowCount() > 0) {
        let msg = " 마감처리종목중 종목코드가 삭제된 종목이 있어 마감처리를 하실 수 없습니다.\n 시스템담당자에게 연락바랍니다." + "\n " + "\n 코드 삭제종목";
        for (let i = 0, k = 1; i < dts_IsuDelChk.getRowCount();
            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************
            i++, k++) {
            msg += "\n 종목코드 = [" + dts_IsuDelChk.getCellData(k, "ISU_CD") + "], 종목명 = " + dts_IsuDelChk.getCellData(k, "ISU_NM");
        }
        await $c.win.alert(msg);
        isTrue = false;
    } else {
        isTrue = true;
    }
    return isTrue;
};

