/**
 * @method
 * @name trsend
 * @description trsend 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trsend = async function() {
    scwin.procJob = '마감처리';
    if (!await scwin.checkProcDt(scwin.procJob)) return;
    if (edt_LIST_DD.getValue() === "") {
        await $c.win.alert("[상장일]이 없습니다.");
        edt_LIST_DD.focus();
        return;
    }
    if (!await scwin.isuDelCheck()) return;
    dts_Item.insertRow();
    dts_Item.setCellData(1, "LIST_DD", edt_LIST_DD.getValue());
    dts_Item.setCellData(1, "CHRG_EMP_NO", js_emp_no);
    dts_Item.setCellData(1, "CLS_TYPE", "TR"); // 이번트를 발생시키키위해 가비지 데이터를 넣어준다.
    // alert('dts_Item'+dts_Item.text)

    let res = await scwin.unRcvIsuCheck();
    if (res === null) {
        res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.procJob));
    }
    if (res) {
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ElwListedReceive.do",
            ref : "dts_Item",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

