/**
 * @method
 * @name setButton
 * @description 권한
 * @returns {void}
 * @hidden N
 */
scwin.setButton = function() {
    if (dts_Item.getCellData(1, "BZ_CLS_TM") !== "") {
        btn_TrSend.setBackgroundImage("../img/btn_ClsPrc_d.gif");
        btn_TrSend.setDisabled(true);
        btn_ReTrSend.hide();
    } else {
        btn_TrSend.setBackgroundImage("../img/btn_ClsPrc.gif");
        btn_TrSend.setDisabled(false);
        btn_ReTrSend.hide();
    }

    // 재마감 처리 버튼 - 시스템 관리자
    if (js_dep_cd === 'ZSYS') {
        btn_ReTrSend.setBackgroundImage("../img/btn_ReCls.gif");
        btn_ReTrSend.setDisabled(false);
        btn_ReTrSend.show("");
    }
};

/**
 * @method
 * @name setSndRcvCorrYn
 * @description set Snd Rcv Corr Yn 처리
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setSndRcvCorrYn = function(dtsObj) {
    let corrYn = '-';
    if (txb_RCV_TM.getValue() !== "") {
        // alert('txb_RCV_TM:'+getObjectValue(txb_RCV_TM));
        // alert('tdtsObj.CountRow:'+dtsObj.CountRow);
        for (let i = 1; i <= dtsObj.getRowCount(); i++) {
            if (dtsObj.getCellData(i, "SNDRCV_DATA_CORR_YN") !== "O") {
                corrYn = 'X';
                break;
            }
            corrYn = 'O';
        }
    }
    // alert('corrYn:'+corrYn);
    return corrYn;
};

/**
 * @method
 * @name checkProcDt
 * @description check Proc Dt 처리
 * @param {String} str str
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkProcDt = async function(str) {
    let vCurDate = $c.ut.cGetToday("yyyymmdd");
    let pCheck = true;
    if (edt_TASK_DD.getValue() !== vCurDate) {
        await $c.win.alert("[마감일]이 현재일경우만 '" + str + "'를 할수 있습니다.");
        pCheck = false;
    }
    if (pCheck) {
        for (let i = 1; i <= dts_New_Proc.getRowCount(); i++) {
            if (dts_New_Proc.getCellData(i, "ELW_ISU_MKTPARTC_NM") === "") {
                await $c.win.alert("발행회사명에 대한 시장참가자번호가 없는 종목이 있습니다. 시스템관리자에게 문의바랍니다.");
                pCheck = false;
                break;
            }
            if (dts_New_Proc.getCellData(i, "ISU_SHRS") <= 0) {
                await $c.win.alert("LP보유량이 '0'인 종목이 있습니다. 확인하여주십시오.");
                pCheck = false;
                break;
            }
        }
    }
    return pCheck;
};

/**
 * @method
 * @name btnDisable
 * @description 팀장확인 2010.0625
 * @returns {void}
 * @hidden N
 */
scwin.btnDisable = function() {
    if (scwin.pJobTitl === "03") {
        // 담당자
        if (txb_APPROV_EMP_NM.getValue() === "") {
            // 담당자확인을 않했을 경우
            btn_rcvApprove.setBackgroundImage("../img/btn/btn_revw.gif");
            btn_rcvApprove.setDisabled(false);
        } else {
            btn_rcvApprove.setBackgroundImage("../img/btn/btn_revw_d.gif");
            btn_rcvApprove.setDisabled(true);
        }
        btn_rcvTeamleadr.setBackgroundImage("../img/btn_BosApv_d.gif");
        btn_rcvTeamleadr.setDisabled(true);
    } else {
        // 팀장
        if (txb_APPROV_EMP_NM.getValue() === "") {
            // 담당자확인을 않했을 경우
            btn_rcvApprove.setBackgroundImage("../img/btn/btn_revw.gif");
            btn_rcvApprove.setDisabled(false);
            btn_rcvTeamleadr.setBackgroundImage("../img/btn_BosApv_d.gif");
            btn_rcvTeamleadr.setDisabled(true);
        } else {
            btn_rcvApprove.setBackgroundImage("../img/btn/btn_revw_d.gif");
            btn_rcvApprove.setDisabled(true);
            if (txb_TEAMLEADR_EMP_NM.getValue() === "") {
                btn_rcvTeamleadr.setBackgroundImage("../img/btn_BosApv.gif");
                btn_rcvTeamleadr.setDisabled(false);
            } else {
                btn_rcvTeamleadr.setBackgroundImage("../img/btn_BosApv_d.gif");
                btn_rcvTeamleadr.setDisabled(true);
            }
            btn_rcvApprove.setBackgroundImage("../img/btn/btn_revw_d.gif");
            btn_rcvApprove.setDisabled(true);
        }
    }
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        $c.data.downloadGridViewExcel(grd_New_Proc, {fileName: "신규상장 마감처리목록", type: "8"});
        $c.data.downloadGridViewExcel(grd_Add_Proc, {fileName: "추가상장 송신목록", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        $c.data.downloadGridViewExcel(grd_New_Search, {fileName: "신규상장 마감처리목록", type: "8"});
        $c.data.downloadGridViewExcel(grd_Add_Search, {fileName: "추가상장 송신목록", type: "8"});
    }
};
